import { HttpClient, HttpHeaders, HttpParams } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import {
  AsmAdapter,
  CUSTOMER_LISTS_NORMALIZER,
  CUSTOMER_SEARCH_PAGE_NORMALIZER,
} from '@spartacus/asm/core';
import {
  AsmConfig,
  AsmSessionCreationOptions,
  BindCartParams,
  CustomerListsPage,
  CustomerRegistrationForm,
  CustomerSearchOptions,
  CustomerSearchPage,
} from '@spartacus/asm/root';
import {
  BaseSiteService,
  ConverterService,
  InterceptorUtil,
  LoggerService,
  OccEndpointsService,
  USE_CUSTOMER_SUPPORT_AGENT_TOKEN,
  User,
  UserIdService,
  tryNormalizeHttpError,
} from '@spartacus/core';
import { Observable } from 'rxjs';
import { catchError } from 'rxjs/operators';

interface CustomerSearchParams {
  /**
   * Supported parameters for searching
   */
  query?: string;
  orderId?: string;
  customerListId?: string;
}

@Injectable()
export class OccAsmAdapter implements AsmAdapter {
  private activeBaseSite: string;
  private currentUserId: string;

  protected logger = inject(LoggerService);
  protected userIdService = inject(UserIdService);

  constructor(
    protected http: HttpClient,
    protected occEndpointsService: OccEndpointsService,
    protected converterService: ConverterService,
    protected config: AsmConfig,
    protected baseSiteService: BaseSiteService
  ) {
    this.baseSiteService
      .getActive()
      .subscribe((value) => (this.activeBaseSite = value));

    this.userIdService
      .getUserId()
      .subscribe((value) => (this.currentUserId = value));
  }

  createAsmSessionEvent(options: AsmSessionCreationOptions): Observable<void> {
    const headers = this.getHeaders();
    const params: HttpParams = new HttpParams();

    const requestBody = {
      ...options,
    };

    const url = this.occEndpointsService.buildUrl(
      'asmSessionEvent',
      {
        urlParams: {
          baseSiteId: this.activeBaseSite,
          userId: this.currentUserId,
        },
      },
      {
        baseSite: false,
        prefix: false,
      }
    );

    return this.http.post<void>(url, requestBody, { headers, params }).pipe(
      catchError((error) => {
        throw tryNormalizeHttpError(error, this.logger);
      })
    );
  }

  protected getHeaders(): HttpHeaders {
    return InterceptorUtil.createHeader(
      USE_CUSTOMER_SUPPORT_AGENT_TOKEN,
      true,
      new HttpHeaders()
    );
  }

  customerLists(): Observable<CustomerListsPage> {
    const headers = this.getHeaders();
    const params: HttpParams = new HttpParams().set(
      'baseSite',
      this.activeBaseSite
    );

    const url = this.occEndpointsService.buildUrl(
      'asmCustomerLists',
      {},
      {
        baseSite: false,
        prefix: false,
      }
    );

    return this.http.get<CustomerListsPage>(url, { headers, params }).pipe(
      catchError((error) => {
        throw tryNormalizeHttpError(error, this.logger);
      }),
      this.converterService.pipeable(CUSTOMER_LISTS_NORMALIZER)
    );
  }

  customerSearch(
    options: CustomerSearchOptions
  ): Observable<CustomerSearchPage> {
    const headers = this.getHeaders();
    let params: HttpParams = new HttpParams().set(
      'baseSite',
      this.activeBaseSite
    );

    const searchBody: CustomerSearchParams = {};

    if (options.sort !== undefined) {
      params = params.set('sort', options.sort);
    } else {
      if (!options.customerListId) {
        params = params.set('sort', 'byNameAsc');
      }
    }

    if (options.query !== undefined) {
      searchBody.query = options.query;
    }
    if (options.orderId !== undefined) {
      searchBody.orderId = options.orderId;
    }

    if (options.pageSize !== undefined) {
      params = params.set('pageSize', options.pageSize.toString());
    }

    if (options.page !== undefined) {
      params = params.set('page', options.page.toString());
    }

    if (options.customerListId !== undefined) {
      searchBody.customerListId = options.customerListId;
    }

    const url = this.occEndpointsService.buildUrl(
      'asmCustomerSearch',
      {},
      {
        baseSite: false,
        prefix: false,
      }
    );

    return this.http
      .post<CustomerSearchPage>(url, searchBody, { headers, params })
      .pipe(
        catchError((error) => {
          throw tryNormalizeHttpError(error, this.logger);
        }),
        this.converterService.pipeable(CUSTOMER_SEARCH_PAGE_NORMALIZER)
      );
  }

  bindCart({ cartId, customerId }: BindCartParams): Observable<unknown> {
    const headers = InterceptorUtil.createHeader(
      USE_CUSTOMER_SUPPORT_AGENT_TOKEN,
      true,
      new HttpHeaders().set('Content-Type', 'application/x-www-form-urlencoded')
    );
    const params: HttpParams = new HttpParams().set(
      'baseSite',
      this.activeBaseSite
    );

    const body = new URLSearchParams();
    body.set('cartId', cartId);
    body.set('customerId', customerId);

    const url = this.occEndpointsService.buildUrl(
      'asmBindCart',
      {},
      {
        baseSite: false,
        prefix: false,
      }
    );

    return this.http.post<void>(url, body, { headers, params }).pipe(
      catchError((error) => {
        throw tryNormalizeHttpError(error, this.logger);
      })
    );
  }

  createCustomer(user: CustomerRegistrationForm): Observable<User> {
    const headers = this.getHeaders();
    const params: HttpParams = new HttpParams().set(
      'baseSite',
      this.activeBaseSite
    );

    const url = this.occEndpointsService.buildUrl(
      'asmCreateCustomer',
      {},
      {
        baseSite: false,
        prefix: false,
      }
    );
    return this.http.post<User>(url, user, { headers, params }).pipe(
      catchError((error) => {
        throw tryNormalizeHttpError(error, this.logger);
      })
    );
  }
}
